def solve(g):
    H,W=len(g),len(g[0])
    cnt=Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    colors=[c for c,v in cnt.items() if c!=bg]
    out=[r[:] for r in g]
    # find full horizontal lines of a color
    hl={}  # color -> rows fully that color
    for r in range(H):
        for c in range(W):
            v=g[r][c]
            if v==bg: continue
            if all(g[r][cc]==v for cc in range(W)): hl.setdefault(v,[]).append(r)
            elif all(g[rr][c]==v for rr in range(H)): hl.setdefault(v,[]).append(c)
    h={k:v for k,v in hl.items()}
    return out
